// Clean-room TSVC s1119 profile; see package rights note.
#[no_mangle]
pub unsafe extern "C" fn tsvc_s1119_same_column_matrix_prefix(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<10||length>130{return -1;}let v=core::slice::from_raw_parts(input,length);let nr=v[0];let passes=v[1];if !(2..=8).contains(&nr)||!(1..=4).contains(&passes){return -1;}let n=nr as usize;let nn=n*n;if length!=2+2*nn{return -1;}let mut a=[0i64;64];let mut b=[0i64;64];for i in 0..nn{let x=v[2+i];let y=v[2+nn+i];if !(-1..=1).contains(&x)||!(-1..=1).contains(&y){return -1;}a[i]=x;b[i]=y;}if output.is_null()||capacity<8*nn{return -2;}for _ in 0..passes{for i in 1..n{for j in 0..n{a[i*n+j]=a[(i-1)*n+j]+b[i*n+j];}}}for i in 0..nn{let bits=a[i]as u64;for j in 0..8{output.add(8*i+j).write((bits>>(8*j))as u8);}}nn as i64}
